import argparse
from pathlib import Path
import pandas as pd
import matplotlib.pyplot as plt


def load_frequency_csv(csv_path: Path) -> pd.DataFrame:
    """Load the frequency CSV generated by ``run_parameter_frequency_analysis``.

    Expected columns (as produced by the pipeline)::

        event_id, typology, total_buildings, parameter_source,
        parameter_id, parameter, frequency, frequency_percentage
    """
    df = pd.read_csv(csv_path)
    # Ensure proper column types
    df["frequency"] = pd.to_numeric(df["frequency"], errors="coerce").fillna(0).astype(int)
    df["frequency_percentage"] = (
        pd.to_numeric(df["frequency_percentage"].str.rstrip("%"), errors="coerce")
        .fillna(0)
        .astype(float)
    )
    return df


def plot_by_typology(
    df: pd.DataFrame,
    typology: str,
    output_dir: Path,
    mode: str = "count",
    stacked: bool = False,
) -> None:
    """Create a bar plot for a single typology.

    Parameters
    ----------
    df:
        Full dataframe containing all typologies.
    typology:
        The typology to filter on (e.g. ``RC`` or ``RRSM``).
    output_dir:
        Directory where the PNG files will be saved.
    mode:
        ``count`` – plot ``frequency`` (raw building count).
        ``percentage`` – plot ``frequency_percentage``.
    stacked:
        If ``True`` a stacked bar chart is produced where each
        ``parameter_source`` forms a separate stack.
    """
    sub = df[df["typology"] == typology]
    if sub.empty:
        raise ValueError(f"No data found for typology '{typology}'.")

    # Sort by the value we are going to plot, descending for readability
    sort_col = "frequency" if mode == "count" else "frequency_percentage"
    sub = sub.sort_values(sort_col, ascending=False)

    output_dir.mkdir(parents=True, exist_ok=True)
    plt.figure(figsize=(12, 6))

    if stacked:
        # Pivot to get a matrix of sources x parameters
        pivot = sub.pivot_table(
            index="parameter_id",
            columns="parameter_source",
            values=sort_col,
            aggfunc="first",
            fill_value=0,
        )
        # Ensure a deterministic order of sources (alphabetical)
        sources = sorted(pivot.columns.tolist())
        pivot = pivot[sources]
        pivot.plot(kind="bar", stacked=True, ax=plt.gca(), colormap="tab20")
        plt.ylabel(
            "Building count" if mode == "count" else "Frequency percentage"
        )
        plt.title(f"{typology} – Parameter frequency by source (stacked)")
        plt.legend(title="Source", bbox_to_anchor=(1.05, 1), loc="upper left")
    else:
        # Simple bar plot – one bar per parameter
        x = sub["parameter_id"]
        y = sub[sort_col]
        plt.bar(x, y, color="#4C78A8")
        plt.ylabel(
            "Building count" if mode == "count" else "Frequency percentage"
        )
        plt.title(
            f"{typology} – Parameter {('count' if mode == 'count' else 'percentage')}"
        )
        plt.xticks(rotation=45, ha="right")

    plt.tight_layout()
    out_path = output_dir / f"{typology}_parameter_{mode}{'_stacked' if stacked else ''}.png"
    plt.savefig(out_path, dpi=140)
    plt.close()
    print(f"Saved plot -> {out_path}")


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Plot parameter‑frequency data produced by the seismic‑damage pipeline.",
        formatter_class=argparse.ArgumentDefaultsHelpFormatter,
    )
    parser.add_argument(
        "--csv",
        type=Path,
        required=True,
        help="Path to the CSV file generated by run_parameter_frequency_analysis().",
    )
    parser.add_argument(
        "--typology",
        type=str,
        required=True,
        help="Typology to visualise (e.g. RC, RRSM, BCBM).",
    )
    parser.add_argument(
        "--out-dir",
        type=Path,
        default=Path.cwd() / "parameter_plots",
        help="Directory where PNG files will be written.",
    )
    parser.add_argument(
        "--mode",
        choices=["count", "percentage"],
        default="count",
        help="Y‑axis metric – raw building count or percentage.",
    )
    parser.add_argument(
        "--stacked",
        action="store_true",
        help="Create a stacked bar chart by parameter_source.",
    )
    args = parser.parse_args()

    df = load_frequency_csv(args.csv)
    plot_by_typology(
        df,
        typology=args.typology,
        output_dir=args.out_dir,
        mode=args.mode,
        stacked=args.stacked,
    )


if __name__ == "__main__":
    main()
